<div class="card-soft"><div class="table-responsive-card"><table class="table mb-0 align-middle"><thead><tr><th><?= e(__('employee')) ?> / <?= e(__('date')) ?></th><th><?= e(__('attendance_details')) ?></th><th><?= e(__('balances')) ?></th><th><?= e(__('decision')) ?></th></tr></thead><tbody>
