<?php foreach ($rows as $row): $replacement=(int)$row['replacement_balance']; $cuti=(int)$row['cuti_balance']; ?><tr><td><strong><?= e($row['full_name']) ?></strong><br><span class="form-hint"><?= e($row['employee_id']) ?> · <?= e(format_date($row['work_date'])) ?></span></td><td><?= e(format_datetime($row['clock_in'])) ?> → <?= e(format_datetime($row['clock_out'])) ?><br><span class="form-hint"><?= e(__('breaks')) ?> <?= e(format_minutes((int)$row['total_break_minutes'])) ?> · <?= e(__('shift_duration')) ?> <?= e(format_minutes((int)$row['shift_minutes'])) ?> · <?= e(__('actual_working_time')) ?> <?= e(format_minutes((int)$row['work_minutes'])) ?></span></td><td><span class="form-hint"><?= e(__('replacement_off_available')) ?></span><br><strong><?= $replacement ?> <?= e($replacement === 1 ? __('day') : __('days')) ?></strong><br><span class="form-hint"><?= e(__('cuti_perlu_ganti')) ?></span><br><strong><?= $cuti ?> <?= e($cuti === 1 ? __('day') : __('days')) ?></strong></td><td><?php if ($row['status']==='pending'): ?><form method="post" class="d-grid gap-2" style="min-width:210px"><?= csrf_field() ?><input type="hidden" name="review_id" value="<?= (int)$row['id'] ?>"><select name="decision" class="form-select form-select-sm" required><option value="replacement_off"><?= e(__('decision_replacement_off')) ?></option><option value="settle_cuti_ganti"><?= e(__('decision_settle_cuti')) ?></option><option value="no_adjustment"><?= e(__('decision_no_adjustment')) ?></option></select><textarea name="admin_note" class="form-control form-control-sm" rows="2" placeholder="<?= e(__('admin_note')) ?>"></textarea><label class="small"><input type="checkbox" name="override_negative" value="1"> <?= e(__('negative_balance_override')) ?></label><button class="btn btn-sm btn-accent"><?= e(__('save_decision')) ?></button></form><?php else: ?><span class="badge text-bg-secondary"><?= e(__('decision_'.(string)$row['decision'])) ?></span><?php if ($row['decision']!=='no_adjustment' && $row['status']==='decided'): ?><form method="post" class="mt-2"><?= csrf_field() ?><input type="hidden" name="action" value="reverse"><input type="hidden" name="review_id" value="<?= (int)$row['id'] ?>"><input name="admin_note" class="form-control form-control-sm mb-1" required placeholder="<?= e(__('reversal_note')) ?>"><button class="btn btn-sm btn-outline-danger"><?= e(__('reverse_decision')) ?></button></form><?php endif; ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
